function getStatusColor(status) {
    const s = status.toLowerCase();
    if ([
        'completed',
        'delivered'
    ].includes(s)) return 'text-green-600 bg-green-100';
    if ([
        'cancelled',
        'failed'
    ].includes(s)) return 'text-red-600 bg-red-100';
    if ([
        'pending',
        'processing'
    ].includes(s)) return 'text-amber-600 bg-amber-100';
    return 'text-slate-600 bg-slate-100';
}
